  console.log("PARENT");
});
// Po dodaniu stopPropagation w #child-div, klikniecie w #child-div
// wypisze TYLKO "CHILD" - "PARENT" NIE wypisze sie, bo propagacja zostala zatrzymana

// preventDefault() blokuje DOMYSLNA AKCJE przegladarki zwiazana z danym
// zdarzeniem (np. wyslanie formularza, otwarcie linku, pokazanie menu
// kontekstowego) - NIE ma wplywu na to, czy zdarzenie 'wedruje' dalej
// w gore drzewa DOM do innych elementow.
//
// stopPropagation() zatrzymuje 'wedrowke' zdarzenia W GORE drzewa DOM
// (proces zwany bubbling, lekcja 5) - NIE ma wplywu na domyslna akcje
// przegladarki (np. formularz nadal zostalby wyslany, gdyby nie uzyto
// TAKZE preventDefault()).
//
// Sa to DWIE NIEZALEZNE metody - mozna uzyc jednej, drugiej, lub obu
// naraz, w zaleznosci od potrzeb.

